src = open('exact.py').read()
start = src.index("    # ---- matrices ---")
end = src.index("    # ---- safety and warmup ---")
new = '''    # ---- matrices ---
    pb = proposal.get('bounds_as')
    pa = proposal.get('age_rounds')
    pp = proposal.get('pred')
    if not isinstance(pb, list) or len(pb) != P:
        return {'valid': False}
    if not isinstance(pa, list) or len(pa) != P:
        return {'valid': False}
    if not isinstance(pp, list) or len(pp) != P:
        return {'valid': False}
    B = [None] * V
    A = [None] * V
    PR = [None] * V
    for p in range(P):
        rb = pb[p]
        ra = pa[p]
        rp = pp[p]
        if not isinstance(rb, list) or len(rb) != N:
            return {'valid': False}
        if not isinstance(ra, list) or len(ra) != N:
            return {'valid': False}
        if not isinstance(rp, list) or len(rp) != N:
            return {'valid': False}
        base = p * N
        for i in range(N):
            b = rb[i]
            a = ra[i]
            if b is None and a is None:
                continue
            if b is None or a is None:
                return {'valid': False}
            if not is_int(b) or not is_int(a):
                return {'valid': False}
            if b < 0 or a < 0:
                return {'valid': False}
            B[base + i] = b
            A[base + i] = a
        PR[base:base + N] = rp
    for u in range(V):
        c = PR[u]
        if c is None:
            continue
        if not isinstance(c, list) or len(c) != 2:
            return {'valid': False}
        pv = c[0]
        kind = c[1]
        if not is_int(pv) or not is_int(kind):
            return {'valid': False}
        if pv < 0 or pv >= V:
            return {'valid': False}
    for u in range(V):
        p, i = divmod(u, N)
        if fab.is_anchor(i, p):
            if B[u] != 0 or A[u] != 0 or PR[u] is not None:
                return {'valid': False}
        elif B[u] is None:
            if PR[u] is not None:
                return {'valid': False}
        else:
            if PR[u] is None:
                return {'valid': False}
    # ---- witness chains and certificate inequalities ----
    order = sorted((u for u in range(V) if B[u] is not None), key=lambda u: A[u])
    rooted = [False] * V
    vT = fab.vT
    gthresh = g * fab.NCODE
    out = fab.out
    if out is None:
        fab.build_edges()
        out = fab.out
    for u in order:
        p, i = divmod(u, N)
        if fab.is_anchor(i, p):
            rooted[u] = True
        else:
            pv, kind = PR[u]
            if B[pv] is None:
                return {'valid': False}
            if kind == -1:
                pp2 = p - 1
                if pp2 < 0:
                    pp2 += P
                if pv != pp2 * N + i:
                    return {'valid': False}
                cost = vT[i][pp2]
                inc = 1
            elif 0 <= kind < 2 * fab.NL:
                psrc = pv // N
                info = fab.step_info(psrc, kind, g)
                if info is None:
                    return {'valid': False}
                dest, cost, inc = info
                if dest != u:
                    return {'valid': False}
                if fab.codedata[kind][0] != pv - psrc * N:
                    return {'valid': False}
            else:
                return {'valid': False}
            if B[u] != B[pv] + cost or A[u] != A[pv] + inc:
                return {'valid': False}
            rooted[u] = rooted[pv]
        # certificate inequality for every allowed step out of this cell
        nd = (p + 1) * N + i if p + 1 < P else i
        if B[nd] is None:
            return {'valid': False}
        wcost = vT[i][p]
        if B[nd] > B[u] + wcost or (B[nd] == B[u] + wcost and A[nd] > A[u] + 1):
            return {'valid': False}
        lst = out[u]
        if lst:
            bu = B[u]
            au = A[u]
            for dest, key, gc in lst:
                if gc < gthresh:
                    continue
                if B[dest] is None:
                    return {'valid': False}
                nb = bu + (key >> SHIFT)
                if B[dest] > nb or (B[dest] == nb and
                                    A[dest] > au + (key & AGE_MASK)):
                    return {'valid': False}
    for u in range(V):
        if B[u] is not None and not rooted[u]:
            return {'valid': False}
    del PR
    del B
    del A
'''
src = src[:start] + new + src[end:]
open('exact.py','w').write(src)
print('ok')
